/**
 * Base interface for all webhook request bodies from District Settings.
 *
 * All webhook calls include a JWT token for authentication and validation.
 */
export interface BaseWebhookBody {
    /**
     * The standard JWT token. It will have the following standard attributes:
     *
     * kid: The id of the encryption key used to sign the payload.
     * iss: The URL that identifies the District Settings environment that issued this token.
     * aud: The recipient for which the JWT was issued. The aud will be set to the schema and host where the request is sent.
     * exp: The expiration time on or after which the JWT is expired. By default, the exp will be 5 minutes after the iat.
     * iat: The time at which the JWT was issued.
     */
    token: string;
}
/**
 * JWT header structure with algorithm and key information.
 */
export interface JWTHeader {
    alg: string;
    typ: string;
    kid: string;
}
/**
 * Base payload structure for District Settings JWT tokens.
 *
 * Contains standard JWT claims including issuer, audience, and expiration.
 */
export interface BaseJWTPayload {
    iss: string;
    aud: string;
    exp: number;
    iat: number;
}
/**
 * Complete JWT structure with header, payload, and signature.
 */
export interface BaseJWT {
    header: JWTHeader;
    payload: BaseJWTPayload;
    signature: string;
}
export type DeleteProductsWebhookBody = BaseWebhookBody;
/**
 * Webhook request body for product addition events.
 *
 * Sent when a product is enabled for a district.
 */
export interface PostProductsWebhookBody extends BaseWebhookBody {
    /**
     * The short name that identifies the product that is being onboarded. The valid list of
     * product short names can be found here.
     */
    product: string;
    /**
     * The UID that uniquely identifies this district across all PowerSchool products. Formerly
     * known as the MOTU GUID.
     */
    districtUid: string;
}
/**
 * Webhook request body for district addition events.
 *
 * Sent when a district is added or enabled. May include OAuth client credentials
 * for authenticating with the District Settings API.
 */
export interface PostTenantsWebhookBody extends BaseWebhookBody {
    /**
     * The short name that identifies the product that is being onboarded. The valid list of
     * product short names can be found here.
     */
    product: string;
    /**
     * The UID that uniquely identifies this district across all PowerSchool products. Formerly
     * known as the MOTU GUID.
     */
    districtUid: string;
    /**
     * (Optional) The OAuth client id that can be used to authenticate with the District Settings
     * API.
     */
    clientId: string;
    /**
     * (Optional) The OAuth client secret that can be used to authenticate with the District
     * Settings API.
     */
    clientSecret: string;
}
/**
 * Decodes a JWT token without verifying the signature.
 *
 * Splits the token into its three components and decodes the base64-encoded
 * header and payload sections.
 *
 * @param token - The JWT token to decode
 * @returns Promise resolving to the decoded JWT structure
 * @throws Error if the token is not a valid JWT format
 */
export declare function decodeToken(token: string): Promise<BaseJWT>;
